import sys

def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    ops = [(data[1 + 2 * i], int(data[2 + 2 * i])) for i in range(q)]
    vals = sorted({x for _, x in ops})
    idx = {v: i + 1 for i, v in enumerate(vals)}
    m = len(vals)
    tree = [0] * (m + 1)
    seen = set()
    out = []
    for t, x in ops:
        k = idx[x]
        if t == 'T':
            seen.add(x)
            while k <= m:
                tree[k] += 1
                k += k & -k
        else:
            if x not in seen:
                out.append(-1)
            else:
                s = 0
                while k > 0:
                    s += tree[k]
                    k -= k & -k
                out.append(s - 1)
    print('\n'.join(map(str, out)))

